#pragma once

namespace fhmi::gbk {

// GBK's two-byte characters as Python's gbk codec reads them, so decoding needs no ICU. Row
// (lead - 0x81), column trail - 0x40, or trail - 0x41 past 0x7F, which is never a trail byte;
// 0 where Python has no character. src/core/gbk_table.cpp is generated by tools/gen_gbk_table.py.
constexpr int kLeadCount = 126;  // 0x81..0xFE
constexpr int kTrailCount = 190; // 0x40..0xFE without 0x7F

extern const char16_t kTable[kLeadCount * kTrailCount];

} // namespace fhmi::gbk
